lemma coordinateOscillation_finAvg_last {n : ℕ} (f : (Fin (n + 1) → α) → ℝ) {d : ℝ}
    (hf : CoordinateOscillation f d) :
    CoordinateOscillation (fun x : Fin n → α ↦ finAvg (fun a ↦ f (Fin.snoc x a))) d

lemma lt_rectDisc {X : Finset (ℝ × ℝ)} {k : ℝ}
    (h : ∀ χ : X → ℤˣ, ∃ a b : ℝ × ℝ, k < |(colorSum X χ (Set.Icc a b) : ℝ)|) :
    k < rectDisc X

theorem condExp_ae_eq_dyadicMean (r : ℕ) {f : ℝ → ℝ}
    (hf : Integrable f μI) :
    μI[f | gridSigma (2 ^ r)] =ᵐ[μI] gridMean f (2 ^ r)

theorem condExp_sub_gridMean (n : ℕ) (hn : 0 < n) {f : ℝ → ℝ}
    (hf : Integrable f μI) :
    μI[(f - gridMean f n) | gridSigma n] =ᵐ[μI] 0

lemma finiteGridIndex_lt_iff {K : ℕ} (hK : 0 < K) {x : ℝ}
    (hx : x ∈ Set.Ioc (0 : ℝ) 1) (s : ℕ) :
    (finiteGridIndex K hK x).val < s ↔ x ≤ (s : ℝ) / K

lemma point_event_eq_coordinate_event {n : ℕ} (S : Set (Fin n → ℝ × ℝ)) :
    pointSampleLaw n S = ((coordinateSampleLaw n).prod (coordinateSampleLaw n))
      {UV | (fun i => (UV.1 i, UV.2 i)) ∈ S}

lemma density_bound {b : ℝ} (hb : 8 ≤ b) {n k : ℕ}
    (hk : Admissible b n k) (hmax : ∀ m, Admissible b n m → m ≤ k) :
    (n : ℝ) ≤ (k + 1 : ℝ) * b ^ k / (4 * b ^ 3)

lemma failure_exponent {A : ℝ} (hA : 0 < A) {L : ℕ}
    (hL : 4 * (A + 5) ≤ (L : ℝ)) :
    A + Real.log 2 ≤ Real.log ((2 : ℝ) ^ L) / 2 - 2 * Real.log 2 - 5 / 4

lemma le_supNorm (χ : Fin n → ℤˣ) (P : Fin n → ℝ × ℝ) {x y : ℝ}
    (hx : x ∈ Set.Icc (0 : ℝ) 1) (hy : y ∈ Set.Icc (0 : ℝ) 1) :
    |F χ P x y| ≤ supNorm χ P

lemma card_eq_sum_fiber_card {ι κ : Type*} [Fintype ι] [Fintype κ]
    [DecidableEq κ] (a : ι → κ) :
    Fintype.card ι = ∑ c : κ, Fintype.card {i : ι // a i = c}
